class Solution:
    def uniformArray(self, nums1: List[int]) -> bool:
        odds = [x for x in nums1 if x % 2]
        evens = [x for x in nums1 if x % 2 == 0]
        if not odds or not evens:            # already one parity
            return True
        # every even must lose a smaller odd to become odd; the smallest odd can never become even
        return min(odds) < min(evens)
